inputs:[["area","Складская площадь, м²","0.01"],["occupancy","Средняя загрузка, %","0.1"],["storage","Ставка хранения, /м²/мес.","0.01"],["volume","Объём обработки, тонн/год","0.01"],["handling","Тариф обработки, /тонна","0.01"],["opex","Годовой OPEX","0.01"],["capex","CAPEX объекта","0.01"],["years","Период расчёта, лет","1"]],
