inputs:[["area","Коммерческая площадь, м²","0.01"],["occupancy","Загрузка, %","0.1"],["rent","Доход от размещения, /м²/мес.","0.01"],["energyMargin","Энергетическая маржа, /м²/год","0.01"],["opex","Годовой OPEX без энергии","0.01"],["capex","CAPEX кластера","0.01"],["years","Период расчёта, лет","1"]],
